import { StyleProp, Text, View, ViewStyle } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

interface ScreenTitleProps {
	title: string
	subtitle?: string
	style?: StyleProp<ViewStyle>
}

export const ScreenTitle = ({ title, subtitle, style }: ScreenTitleProps) => {
	const { theme } = useTheme()

	return (
		<View style={[styles.header, style]}>
			<Text style={styles.title(theme)}>{title}</Text>
			{subtitle && <Text style={styles.subtitle(theme)}>{subtitle}</Text>}
		</View>
	)
}

const styles = defineStyles({
	header: {
		gap: 10,
		marginBottom: 40,
		marginTop: 40
	},
	title: (theme: Theme) => ({
		fontSize: 24,
		fontWeight: '600',
		color: colors[theme].gray[900]
	}),
	subtitle: (theme: Theme) => ({
		fontSize: 16,
		color: colors[theme].gray[500],
		lineHeight: 24
	})
})
